import React from 'react';

const StatusBadge = ({ type, value }) => {
    let backgroundColor = '#e5e7eb'; // default gray
    let color = '#374151';

    if (type === 'status') {
        switch (value) {
            case 'OPEN': backgroundColor = '#dbeafe'; color = '#1e40af'; break; // blue
            case 'IN_PROGRESS': backgroundColor = '#fef3c7'; color = '#b45309'; break; // amber
            case 'RESOLVED': backgroundColor = '#d1fae5'; color = '#065f46'; break; // green
            case 'CLOSED': backgroundColor = '#f3f4f6'; color = '#374151'; break; // gray
            case 'REJECTED': backgroundColor = '#fee2e2'; color = '#b91c1c'; break; // red
            default: break;
        }
    } else if (type === 'priority') {
        switch (value) {
            case 'CRITICAL': backgroundColor = '#fee2e2'; color = '#b91c1c'; break; // red
            case 'HIGH': backgroundColor = '#fef3c7'; color = '#b45309'; break; // amber
            case 'MEDIUM': backgroundColor = '#dbeafe'; color = '#1e40af'; break; // blue
            case 'LOW': backgroundColor = '#f3f4f6'; color = '#374151'; break; // gray
            default: break;
        }
    }

    const style = {
        padding: '0.25rem 0.75rem',
        borderRadius: '9999px',
        fontSize: '0.75rem',
        fontWeight: '600',
        display: 'inline-flex',
        alignItems: 'center',
        justifyContent: 'center',
        backgroundColor,
        color,
        textTransform: 'capitalize'
    };

    return (
        <span style={style}>
            {value ? value.replace('_', ' ').toLowerCase() : ''}
        </span>
    );
};

export default StatusBadge;
